52	// Data structure collecting aggregate transformation metrics for the IR.  These
53	// values are zero-ed at construction time and only increment.
54	struct TransformMetrics {
55	  // Number of nodes added (number of invocations of
56	  // FunctionBase::AddNodeInternal).
57	  int64_t nodes_added = 0;
58	
59	  // Number of nodes removed (number of invocations of
60	  // FunctionBase::RemoveNode).
61	  int64_t nodes_removed = 0;
62	
63	  // Number of nodes replaced (number of calls to Node::ReplaceUsesWith).
64	  int64_t nodes_replaced = 0;
65	
66	  // Number of operands replaced (number of calls to
67	  // Node::ReplaceOperand[Number]).
68	  int64_t operands_replaced = 0;
69	
70	  // Number of operands removed (number of calls to
71	  // Node::RemoveOptionalOperand).
72	  int64_t operands_removed = 0;
73	
74	  static TransformMetrics FromProto(const TransformMetricsProto& proto);
75	  TransformMetrics operator+(const TransformMetrics& other) const;
76	  TransformMetrics operator-(const TransformMetrics& other) const;
77	  std::string ToString() const;
78	  TransformMetricsProto ToProto() const;
79	};
