absl::StatusOr<std::string> Parser::ParsePackageName() {
  XLS_RETURN_IF_ERROR(scanner_.DropKeywordOrError("package"));
  // Package names are identifier-like tokens in IR text. All keywords are
  // contextual in this position and permitted as package names.
  XLS_ASSIGN_OR_RETURN(Token name_token,
                       scanner_.PopKeywordOrIdentToken("package name"));
  return name_token.value();
}

absl::Status Parser::ParseFileNumber(
    Package* package, absl::Span<const IrAttribute> outer_attributes) {
  if (!outer_attributes.empty()) {
    return absl::InvalidArgumentError(
        "Attributes are not supported on file number declarations.");
  }

  if (AtEof()) {
    return absl::InvalidArgumentError("Could not parse function; at EOF.");
  }
  XLS_RETURN_IF_ERROR(scanner_.DropKeywordOrError("file_number"));
  XLS_ASSIGN_OR_RETURN(
      Token file_number_token,
      scanner_.PopTokenOrError(LexicalTokenType::kLiteral, "file number"));
  XLS_ASSIGN_OR_RETURN(
      Token file_path_token,
      scanner_.PopTokenOrError(LexicalTokenType::kQuotedString, "file path"));
  XLS_ASSIGN_OR_RETURN(int64_t file_number, file_number_token.GetValueInt64());
  if (file_number > std::numeric_limits<int32_t>::max()) {
    return absl::InternalError("file_number declaration might overflow");
  }
  package->SetFileno(Fileno(static_cast<int32_t>(file_number)),
                     file_path_token.value());
  return absl::OkStatus();
}

absl::StatusOr<Function*> Parser::ParseFunction(
    Package* package, absl::Span<const IrAttribute> outer_attributes,
    std::unique_ptr<FunctionBase>* overridden_dest) {
  return ParseFunctionInternal(package, outer_attributes, /*scheduled=*/false,
                               overridden_dest);
}

absl::StatusOr<Function*> Parser::ParseFunctionInternal(
    Package* package, absl::Span<const IrAttribute> outer_attributes,
    bool scheduled, std::unique_ptr<FunctionBase>* overridden_dest) {
  if (AtEof()) {
    return absl::InvalidArgumentError("Could not parse function; at EOF.");
  }

  XLS_RETURN_IF_ERROR(
      scanner_.DropKeywordOrError(scheduled ? "scheduled_fn" : "fn"));

  absl::flat_hash_map<std::string, BValue> name_to_value;
  XLS_ASSIGN_OR_RETURN(
      auto function_data,
      ParseFunctionSignature(&name_to_value, package, scheduled));
  FunctionBuilder* fb = function_data.first.get();
  if (overridden_dest != nullptr) {
    fb->OverrideDestination(overridden_dest);
  }

  Function* result = nullptr;
  if (overridden_dest == nullptr) {
    XLS_ASSIGN_OR_RETURN(BodyResult body_result,
                         ParseBody(fb, &name_to_value, package, scheduled));

    XLS_RET_CHECK(std::holds_alternative<FunctionBodyResult>(body_result));
    BValue return_value =
        std::get<FunctionBodyResult>(body_result).return_value;

    if (return_value.valid() &&
        return_value.node()->GetType() != function_data.second) {
      return absl::InvalidArgumentError(
          absl::StrFormat("Type of return value %s does not match declared "
                          "function return type "
                          "%s",
                          return_value.node()->GetType()->ToString(),
                          function_data.second->ToString()));
    }

    // TODO(leary): 2019-02-19 Could be an empty function body, need to decide
    // what to do for those. Accept that the return value can be null and handle
    // everywhere?
    XLS_ASSIGN_OR_RETURN(result, fb->BuildWithReturnValue(return_value));
  } else {
    XLS_RETURN_IF_ERROR(scanner_.DropTokenOrError(
        LexicalTokenType::kCurlClose, "'}' at end of function body"));
    XLS_ASSIGN_OR_RETURN(result, fb->BuildWithNoReturnValue());
  }

  for (const IrAttribute& attribute : outer_attributes) {
    XLS_RETURN_IF_ERROR(absl::visit(
        Visitor{[&](const InitiationInterval& ii) -> absl::Status {
                  result->SetInitiationInterval(ii.value);
                  return absl::OkStatus();
                },
                [&](const ForeignFunctionData& ffi) -> absl::Status {
                  // Dummy parse to make sure it is a valid template.
                  XLS_RETURN_IF_ERROR(
                      CodeTemplate::Create(ffi.code_template()).status());
                  result->SetForeignFunctionData(ffi);
                  return absl::OkStatus();
                },
                [&](const NonSynthMarker&) -> absl::Status {
                  result->set_non_synth(true);
                  return absl::OkStatus();
                },
                [&](const FuzzTestAttribute& fuzz_test_attr) -> absl::Status {
                  std::vector<AttributeData::Argument> args;
                  if (fuzz_test_attr.domains_proto_str.has_value()) {
                    xls::PackageInterfaceProto::Function function_proto;
                    if (!google::protobuf::TextFormat::ParseFromString(
                            *fuzz_test_attr.domains_proto_str,
                            &function_proto)) {
                      return absl::InvalidArgumentError(absl::StrFormat(
                          "Invalid FuzzTestDomain proto string: %s",
                          *fuzz_test_attr.domains_proto_str));
                    }
                    // TODO: davidplass - Typecheck against the function
                    // signature (at least for the correct # of parameters.)
                    args.push_back(AttributeData::StringKeyValueArgument{
                        .first = "domains",
                        .second = *fuzz_test_attr.domains_proto_str,
                        .is_backticked = true});

