267	    const IrAnnotator& annotate) const {
268	  std::string res;
269	  if (IsScheduled()) {
270	    CHECK(!annotate.NodeOrder(const_cast<FunctionBase*>(this)))
271	        << "Cannot use custom node order for scheduled entities";
272	    StageSectioner sectioner(this);
273	    CHECK(sectioner.Run().ok());
274	    for (const std::list<Node*>& section : sectioner.sections()) {
275	      if (section.empty()) {
276	        continue;
277	      }
278	
279	      struct ScheduledAnnotations : public IrAnnotator {
280	       public:
281	        ScheduledAnnotations(Node* outputs_valid, Node* active_inputs_valid)
282	            : outputs_valid_(outputs_valid),
283	              active_inputs_valid_(active_inputs_valid) {}
284	        Annotation NodeAnnotation(Node* node) const override {
285	          if (node == outputs_valid_) {
286	            return {.prefix = "ret"};
287	          } else if (node == active_inputs_valid_) {
288	            return {.prefix = "active_inputs_valid"};
289	          }
290	          return {};
291	        }
292	
293	       private:
294	        Node* outputs_valid_;
295	        Node* active_inputs_valid_;
296	      };
297	
298	      Node* first = *section.begin();
299	      if (IsStaged(first)) {
300	        const Stage& stage = stages()[*GetStageIndex(first)];
301	        IrAnnotatorJoiner joiner(
302	            ScheduledAnnotations(stage.outputs_valid(),
303	                                 stage.active_inputs_valid()),
304	            IrAnnotatorRef(annotate));
305	        if (stage.IsControlled()) {
306	          absl::StrAppendFormat(&res, "  controlled_stage(%s, %s) {\n",
307	                                stage.inputs_valid()->GetName(),
308	                                stage.outputs_ready()->GetName());
309	        } else {
310	          absl::StrAppendFormat(&res, "  stage {\n");
311	        }
312	
313	        for (Node* node : section) {
314	          auto annotation = joiner.NodeAnnotation(node);
315	          if (!annotation.filter) {
316	            absl::StrAppendFormat(&res, "    %s\n",
