338	        auto annotation = annotate.NodeAnnotation(node);
339	        if (!annotation.filter) {
340	          absl::StrAppendFormat(&res, "  %s\n",
341	                                annotation.Decorate(node->ToString()));
342	        }
343	      }
344	    } else {
345	      for (Node* node : nodes()) {
